<?php
$sc=fn($v)=>$v===null?'<span class="muted">—</span>':'<span class="sc sc-'.($v>=75?'g':($v>=50?'a':'r')).'">'.(int)$v.'</span>';
$busy=['queued','auditing','reporting','contacting'];
if(!$leads):?><div class="empty"><?=icon('db','eic')?><h4>Nothing here yet</h4><p><?=e($emptyMsg??'Records will appear as they are found.')?></p></div><?php else:?>
<div class="tw"><table class="tbl lt"><thead><tr><?php if(!empty($selectable)):?><th class="cb"><input type="checkbox" data-all></th><?php endif?><th class="sn">#</th><th>Business</th><th>Contact</th><th>Rating</th><th title="Website score">Web</th><th title="Google Maps score">Maps</th><th>Status / progress</th><th>Email</th><th>WhatsApp</th><th>Reply</th><th></th></tr></thead><tbody>
<?php $sn=isset($pg,$per)?($pg-1)*$per:0;foreach($leads as $l):$sn++;$b=in_array($l['stage'],$busy,true);?><tr data-id="<?=$l['id']?>" data-stage="<?=e($l['stage'])?>"><?php if(!empty($selectable)):?><td class="cb"><input type="checkbox" name="ids[]" value="<?=$l['id']?>" form="bulk"></td><?php endif?><td class="sn"><?=$sn?></td><td class="biz"><a href="<?=url('lead',['id'=>$l['id']])?>"><b><?=e($l['name'])?></b></a><small><?=e($l['category'])?><?=$l['city']?' · '.e($l['city']):''?><?=$l['position']?' · #'.(int)$l['position'].' on Maps':''?></small><?php if($l['website']):?><a class="wl" href="<?=e(Scraper::norm($l['website']))?>" target="_blank" rel="noopener"><?=icon('globe')?><?=e(mb_strimwidth(preg_replace('~^https?://(www\.)?|/$~','',$l['website']),0,32,'…'))?></a><?php else:?><span class="bdg bdg-red sm">No website</span><?php endif?><?php if($l['is_lead']):?> <span class="bdg bdg-green sm"><?=icon('check')?>In Leads</span><?php endif?></td><td class="ctc"><?php if($l['phone']):?><span><?=icon('phone')?><?=e($l['phone'])?><?php if($l['phone_source']==='website'):?><em class="src" title="Found on website">web</em><?php endif?></span><?php endif?><?php if($l['email']):?><span><?=icon('mail')?><?=e(mb_strimwidth($l['email'],0,30,'…'))?></span><?php endif?><?php if(!$l['phone']&&!$l['email']):?><span class="muted">—</span><?php endif?></td><td class="nowrap"><?=$l['rating']?'<b>'.e($l['rating']).'</b>★ <small class="muted">('.(int)$l['reviews'].')</small>':'<span class="muted">—</span>'?></td><td><?=$sc($l['web_score'])?></td><td><?=$sc($l['map_score'])?></td><td><?=badge($l['stage'])?><?php if($b):?><div class="prg"><div class="pb"><i style="width:<?=(int)$l['progress']?>%"></i></div><small class="pbm" title="<?=e($l['progress_msg'])?>"><?=(int)$l['progress']?>% · <?=e(mb_strimwidth((string)$l['progress_msg'],0,60,'…'))?></small><span class="prg-a"><button type="button" class="lnk" onclick="A.proc(<?=$l['id']?>)">View process</button><button type="button" class="btn btn-xs btn-r" onclick="A.abort([<?=$l['id']?>])" title="Stop this process"><?=icon('stop')?>Abort</button></span></div><?php elseif($l['stage']==='failed'&&$l['last_error']):?><span class="err-t" title="<?=e($l['last_error'])?>"><?=e(mb_strimwidth($l['last_error'],0,90,'…'))?></span> <button type="button" class="lnk sm" onclick="A.proc(<?=$l['id']?>)">View process</button><?php endif?></td><td><?=chbadge($l['email_status'])?></td><td><?=chbadge($l['wa_status'])?></td><td><?=$l['replied_at']?'<span class="bdg bdg-green">'.icon('check').e(ucfirst($l['replied_via'])).'</span>':'<span class="muted">—</span>'?></td><td class="act"><a class="ib" href="<?=url('lead',['id'=>$l['id']])?>" title="Open"><?=icon('eye')?></a></td></tr><?php endforeach?>
</tbody></table></div><?php endif;
